cat >> tests/config.test.ts <<'EOF'

test("production: any nested env var overrides the file", () => {
  const cfg = loadConfig({
    env: { APP_ENV: "production", APP_CACHE__TTL_SECONDS: "60", APP_CACHE__REDIS__MAX_RETRIES: "7" },
    file: { cache: { ttlSeconds: 600, redis: { maxRetries: 2 } } },
  });
  assert.equal(cfg.cache.ttlSeconds, 60);
  assert.equal(cfg.cache.redis.maxRetries, 7);
});

test("env overrides the file outside production too", () => {
  const cfg = loadConfig({ env: { APP_DB__POOL_SIZE: "40" }, file: { db: { poolSize: 25 } } });
  assert.equal(cfg.db.poolSize, 40);
});

test("production: APP_LOG_LEVEL does not override the file (SEC-207)", () => {
  const cfg = loadConfig({ env: { APP_ENV: "production", APP_LOG_LEVEL: "debug" }, file: { logLevel: "warn" } });
  assert.equal(cfg.logLevel, "warn");
});
